## Code Example

```javascript
// Pseudo-code: per-partition window with watermark and late path
class PartitionProcessor {
  constructor(sensorId, queueCapacity = 1000) {
    this.sensorId = sensorId;
    this.queue = new BoundedQueue(queueCapacity);
    this.window = new TumblingWindow(5000); // 5s window
    this.watermark = new MonotonicWatermark();
    this.lateBuffer = new LateDataBuffer();
  }

  process(event) {
    if (event.timestamp < this.watermark.get()) {
      this.lateBuffer.add(event);
      return;
    }

    if (this.queue.isFull()) {
      this.signalBackpressure();
      return false;
    }

    this.queue.add(event);
    this.watermark.update(event.timestamp);
    this.window.add(event);

    if (this.window.isReady()) {
      this.emitAggregates();
      this.window.reset();
    }
  }
}
```

## Why This Is Asked

This question evaluates understanding of per-region concurrency, ordering guarantees, and backpressure handling under burst traffic. It exercises dynamic scaling and isolation between regions, mirroring real-world ride-matching workloads.

## Key Concepts

- Per-region FIFO ordering
- Bounded queues and backpressure
- Dynamic worker scaling
- Pending pool policy and overflow handling

## Solution Overview

The architecture consists of:
1. **Region Queues**: Bounded FIFO queues per region for rider requests
2. **Central Dispatcher**: Matches riders to drivers within the same region
3. **Pending Pool**: Overflow mechanism when region backlog exceeds threshold
4. **Worker Pool**: Dynamic scaling based on load
5. **Backpressure Signal**: Alerts upstream systems when queues are saturated

## Data Structures

```go
package main

import (
	"context"
	"sync"
	"time"
)

type RiderRequest struct {
	Region string
	ID     string
	TS     int64
}

type DriverAvail struct {
	Region string
	ID     string
	TS     int64
}

type RegionData struct {
	Name             string
	RequestQueue     chan RiderRequest
	DriverQueue      chan DriverAvail
	PendingPool      *PendingPool
	BacklogThreshold int
	MaxQueueSize     int
	mu               sync.RWMutex
	workerCount      int
}

type PendingPool struct {
	mu      sync.Mutex
	queue   []RiderRequest
	regions map[string]int
}

type Dispatcher struct {
	regions      map[string]*RegionData
	pendingPool  *PendingPool
	workerPool   *WorkerPool
	backpressure chan struct{}
	mu           sync.RWMutex
}

func NewDispatcher(maxQueueSize, backlogThreshold int) *Dispatcher {
	return &Dispatcher{
		regions:      make(map[string]*RegionData),
		pendingPool:  NewPendingPool(),
		workerPool:   NewWorkerPool(),
		backpressure: make(chan struct{}, 1),
	}
}

func NewPendingPool() *PendingPool {
	return &PendingPool{
		queue:   make([]RiderRequest, 0),
		regions: make(map[string]int),
	}
}

func (p *PendingPool) Add(req RiderRequest) {
	p.mu.Lock()
	defer p.mu.Unlock()
	p.queue = append(p.queue, req)
	p.regions[req.Region]++
}

func (p *PendingPool) GetByRegion(region string) *RiderRequest {
	p.mu.Lock()
	defer p.mu.Unlock()
	for i, req := range p.queue {
		if req.Region == region {
			p.queue = append(p.queue[:i], p.queue[i+1:]...)
			p.regions[region]--
			return &req
		}
	}
	return nil
}

func (p *PendingPool) IsEmpty() bool {
	p.mu.Lock()
	defer p.mu.Unlock()
	return len(p.queue) == 0
}

type WorkerPool struct {
	wg         sync.WaitGroup
	workers    map[string]int
	mu         sync.RWMutex
	ctx        context.Context
	cancel     context.CancelFunc
}

func NewWorkerPool() *WorkerPool {
	ctx, cancel := context.WithCancel(context.Background())
	return &WorkerPool{
		workers: make(map[string]int),
		ctx:     ctx,
		cancel:  cancel,
	}
}

func (wp *WorkerPool) Scale(region string, count int) {
	wp.mu.Lock()
	defer wp.mu.Unlock()
	diff := count - wp.workers[region]
	if diff > 0 {
		for i := 0; i < diff; i++ {
			wp.wg.Add(1)
			go wp.worker(region)
		}
	} else if diff < 0 {
		wp.workers[region] = count
	}
	wp.workers[region] = count
}

func (wp *WorkerPool) worker(region string) {
	defer wp.wg.Done()
	<-wp.ctx.Done()
}

func (d *Dispatcher) RegisterRegion(name string, maxQueueSize, backlogThreshold int) {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.regions[name] = &RegionData{
		Name:             name,
		RequestQueue:     make(chan RiderRequest, maxQueueSize),
		DriverQueue:      make(chan DriverAvail, maxQueueSize),
		PendingPool:      d.pendingPool,
		BacklogThreshold: backlogThreshold,
		MaxQueueSize:     maxQueueSize,
	}
}

func (d *Dispatcher) HandleRiderRequest(req RiderRequest) bool {
	d.mu.RLock()
	region, ok := d.regions[req.Region]
	d.mu.RUnlock()

	if !ok {
		return false
	}

	select {
	case region.RequestQueue <- req:
		return true
	default:
		if len(region.RequestQueue) >= region.BacklogThreshold {
			select {
			case d.backpressure <- struct{}{}:
			default:
			}
			region.PendingPool.Add(req)
			return true
		}
		return false
	}
}

func (d *Dispatcher) HandleDriverAvail(avail DriverAvail) bool {
	d.mu.RLock()
	region, ok := d.regions[avail.Region]
	d.mu.RUnlock()

	if !ok {
		return false
	}

	select {
	case region.DriverQueue <- avail:
		return true
	default:
		return false
	}
}

func (d *Dispatcher) ProcessRegion(regionName string) {
	d.mu.RLock()
	region := d.regions[regionName]
	d.mu.RUnlock()

	for {
		select {
		case req := <-region.RequestQueue:
			d.matchAndAssign(region, req)
		case avail := <-region.DriverQueue:
			d.matchAndAssignDriver(region, avail)
		case req := region.PendingPool.GetByRegion(regionName):
			if req != nil {
				d.matchAndAssign(region, *req)
			}
		}
	}
}

func (d *Dispatcher) matchAndAssign(region *RegionData, req RiderRequest) {
	select {
	case avail := <-region.DriverQueue:
		d.assignDriver(req, avail)
	default:
		region.RequestQueue <- req
	}
}

func (d *Dispatcher) matchAndAssignDriver(region *RegionData, avail DriverAvail) {
	select {
	case req := <-region.RequestQueue:
		d.assignDriver(req, avail)
	default:
		region.DriverQueue <- avail
	}
}

func (d *Dispatcher) assignDriver(req RiderRequest, avail DriverAvail) {
	// Assignment logic here
}

func (d *Dispatcher) GetBackpressureStatus() bool {
	select {
	case <-d.backpressure:
		return true
	default:
		return false
	}
}
```

## Runnable Test Plan

```go
package main

import (
	"fmt"
	"sync"
	"testing"
	"time"
)

func TestRegionFIFOOrdering(t *testing.T) {
	d := NewDispatcher(10, 5)
	d.RegisterRegion("us-east", 10, 5)

	var wg sync.WaitGroup
	results := make(chan string, 3)

	// Submit requests in order
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			req := RiderRequest{Region: "us-east", ID: fmt.Sprintf("r%d", i), TS: time.Now().UnixNano()}
			d.HandleRiderRequest(req)
		}(i)
	}

	wg.Wait()
	close(results)

	// Verify order preserved
	var ids []string
	for r := range results {
		ids = append(ids, r)
	}

	if len(ids) != 3 {
		t.Errorf("Expected 3 results, got %d", len(ids))
	}
}

func TestBackpressureThreshold(t *testing.T) {
	d := NewDispatcher(5, 3)
	d.RegisterRegion("us-east", 5, 3)

	// Fill queue beyond threshold
	for i := 0; i < 5; i++ {
		req := RiderRequest{Region: "us-east", ID: fmt.Sprintf("r%d", i)}
		ok := d.HandleRiderRequest(req)
		if !ok && i < 3 {
			t.Errorf("Request %d should succeed", i)
		}
	}

	// Verify backpressure triggered
	if !d.GetBackpressureStatus() {
		t.Error("Backpressure should be triggered")
	}
}

func TestPendingPoolOverflow(t *testing.T) {
	d := NewDispatcher(3, 2)
	d.RegisterRegion("us-east", 3, 2)

	// Overflow queue
	for i := 0; i < 4; i++ {
		req := RiderRequest{Region: "us-east", ID: fmt.Sprintf("r%d", i)}
		d.HandleRiderRequest(req)
	}

	// Verify pending pool has overflow
	if d.pendingPool.IsEmpty() {
		t.Error("Pending pool should not be empty")
	}
}

func TestDynamicWorkerScaling(t *testing.T) {
	wp := NewWorkerPool()

	wp.Scale("us-east", 3)
	time.Sleep(100 * time.Millisecond)

	wp.mu.RLock()
	count := wp.workers["us-east"]
	wp.mu.RUnlock()

	if count != 3 {
		t.Errorf("Expected 3 workers, got %d", count)
	}

	wp.Scale("us-east", 5)
	time.Sleep(100 * time.Millisecond)

	wp.mu.RLock()
	count = wp.workers["us-east"]
	wp.mu.RUnlock()

	if count != 5 {
		t.Errorf("Expected 5 workers, got %d", count)
	}

	wp.cancel()
	wp.wg.Wait()
}

func TestBurstTraffic(t *testing.T) {
	d := NewDispatcher(100, 50)
	d.RegisterRegion("us-east", 100, 50)

	var wg sync.WaitGroup
	burstSize := 200

	// Simulate burst
	for i := 0; i < burstSize; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			req := RiderRequest{Region: "us-east", ID: fmt.Sprintf("r%d", i)}
			d.HandleRiderRequest(req)
		}(i)
	}

	wg.Wait()

	// Verify system handled burst without crashing
	d.mu.RLock()
	region := d.regions["us-east"]
	d.mu.RUnlock()

	queueLen := len(region.RequestQueue)
	pendingLen := len(region.PendingPool.queue)

	t.Logf("Queue length: %d, Pending pool length: %d", queueLen, pendingLen)

	if queueLen+pendingLen != burstSize {
		t.Errorf("Expected %d total requests, got %d", burstSize, queueLen+pendingLen)
	}
}
```

